// Days an issue can sit OPEN at this severity before it auto-bumps to the next level.
// e.g. a Low issue open 2+ days becomes Medium; open 7+ days (2+5) becomes High; etc.
// Escalation only runs while status is "Open" or "In Progress" — Resolved/Closed issues freeze.
const SEVERITY_ESCALATION_DAYS = { Low: 2, Medium: 5, High: 10 };

/* ============================== HELPERS ============================== */
const uid = () => Math.random().toString(36).slice(2, 10);
const todayStr = () => new Date().toISOString().slice(0, 10);
const daysBetween = (a, b) => (new Date(b) - new Date(a)) / 86400000;
const addDaysStr = (dateStr, n) => new Date(new Date(dateStr).getTime() + n * 86400000).toISOString().slice(0, 10);

const isWeekendDay = (dateStr) => {
  const d = new Date(dateStr).getDay(); // 0 = Sun, 6 = Sat
  return d === 0 || d === 6;
};
// If the project doesn't work weekends and this date lands on one, push forward to Monday.
const rollToWorkingDay = (dateStr, worksWeekends) => {
  if (worksWeekends) return dateStr;
  let d = dateStr;
  while (isWeekendDay(d)) d = addDaysStr(d, 1);
  return d;
};
// N working days after startStr (n=0 returns startStr itself), skipping weekends
// entirely when the project doesn't work them.
const addWorkingDaysStr = (startStr, n, worksWeekends) => {
  if (worksWeekends) return addDaysStr(startStr, n);
  let d = startStr;
  let remaining = n;
  while (remaining > 0) {
    d = addDaysStr(d, 1);
    if (!isWeekendDay(d)) remaining--;
  }
  return d;
};

// Status drives progress + the "originally due" snapshot used to colour the Gantt bar —
// shared by TaskModal and the Gantt tab's inline status edit so the two can't diverge.
function statusChangePatch(task, newStatus) {
  const patch = { status: newStatus };
  const today = todayStr();

  if (newStatus === "Completed") {
    patch.progress = 100;
    // Finished past its Finish date: persist the real duration. Without this,
    // the render-time stretch (which only applies while the task is still
    // incomplete) disappears the moment it's marked Completed, and a task
    // that actually ran 3 days snaps back to showing its original 1-day plan.
    if (task.end && task.end < today) {
      patch.plannedEnd = task.plannedEnd || task.end; // original due date, kept as history
      patch.end = today; // actual completion date
    }
    // plannedEnd is deliberately NOT cleared here — it's the permanent record
    // of when the task was originally due, used to render the red overrun tail.
  } else if (newStatus === "Not Started") {
    patch.progress = 0;
    patch.plannedEnd = "";
  } else if (newStatus === "Delayed") {
    if (!task.plannedEnd) patch.plannedEnd = task.end || "";
  } else {
    // In Progress: manually reverting out of Delayed clears the snapshot.
    patch.plannedEnd = "";
  }
  return patch;
}
function applyTargetOverrunPatch(task, projectEndDate) {
  if (!projectEndDate || !task.end) return {};
  if (task.status === "Completed" || task.status === "Delayed") return {};
  if (task.end > projectEndDate) {
    return { status: "Delayed", plannedEnd: task.plannedEnd || projectEndDate };
  }
  return {};
}

// How many days past its Finish date a task is, right now — computed fresh every
// render, never stored. Works regardless of status (Delayed or not), as long as the
// task isn't Completed and its Finish has actually passed.
function daysOverdueCount(task, todayVal) {
  if (!task.end || task.end >= todayVal || task.status === "Completed") return 0;
  return Math.max(1, Math.round(daysBetween(task.end, todayVal)));
}
const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));

