function Modal({ title, onClose, onSubmit, submitLabel = "Save", children, wide }) {
  const ref = useRef(null);
  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [onClose]);
  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4"
      style={{ background: "rgba(6,8,11,0.65)" }}
      onMouseDown={(e) => e.target === e.currentTarget && onClose()}
    >
      <div
        ref={ref}
        className="w-full rounded-xl overflow-hidden flex flex-col"
        style={{
          maxWidth: wide ? 640 : 460,
          maxHeight: "88vh",
          background: T.surface,
          border: `1px solid ${T.border}`,
          boxShadow: "0 24px 60px rgba(0,0,0,0.5)",
        }}
      >
        <div
          className="flex items-center justify-between px-5 py-4 shrink-0"
          style={{ borderBottom: `1px solid ${T.border}` }}
        >
          <h3 className="font-semibold text-[15px]" style={{ color: T.text, fontFamily: "'Space Grotesk', sans-serif" }}>
            {title}
          </h3>
          <IconBtn onClick={onClose} title="Close">
            <X size={16} />
          </IconBtn>
        </div>
        <form
          onSubmit={(e) => {
            e.preventDefault();
            onSubmit();
          }}
          className="overflow-y-auto px-5 py-4 flex flex-col gap-3.5"
        >
          {children}
          <div className="flex justify-end gap-2 pt-2">
            <Button variant="ghost" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit">{submitLabel}</Button>
          </div>
        </form>
      </div>
    </div>
  );
}

