function TaskModal({ data, issues, siteNames, taskNames, presetSite, onClose, onSave }) {
  const [f, setF] = useState(
    data || {
      name: "",
      owner: "",
      site: presetSite || "",
      start: todayStr(),
      end: todayStr(),
      status: "Not Started",
      progress: 0,
      plannedEnd: "",
    }
  );
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });

  // Status drives progress + the "originally due" snapshot used to colour the Gantt bar:
  // - Completed / Not Started have no user-editable progress (locked to 100% / 0%).
  // - The first time a task becomes Delayed, we snapshot its current finish date as
  //   plannedEnd. The Finish field above can then be pushed out to the real new date,
  //   and only the stretch between plannedEnd and the new Finish shows red.
  const setStatus = (e) => {
    const val = e.target.value;
    setF((prev) => ({ ...prev, ...statusChangePatch(prev, val) }));
  };

  const showProgress = f.status === "In Progress" || f.status === "Delayed";
  const isOverdueUnflagged = f.end && f.end < todayStr() && f.status !== "Completed" && f.status !== "Delayed";
  const linkedOpenIssues = data
    ? (issues || []).filter((i) => i.taskId === data.id && (i.status === "Open" || i.status === "In Progress"))
    : [];

  return (
    <Modal title={data ? "Edit task" : "Add task"} onClose={onClose} onSubmit={() => onSave({ ...f, progress: Number(f.progress) || 0 })}>
      <Field label="Task name">
        <TextInput required value={f.name} onChange={set("name")} placeholder="e.g. Site survey" list="task-name-suggestions" />
        <datalist id="task-name-suggestions">
          {(taskNames || []).map((n) => (
            <option key={n} value={n} />
          ))}
        </datalist>
      </Field>
      <p className="text-xs leading-relaxed" style={{ color: T.textFaint }}>
        Tasks with the exact same name group into one row on the Gantt chart — use this for
        the same task repeated across sites (e.g. "Site Assessment" at every site), each with
        its own dates.
      </p>
      <Field label="Owner">
        <TextInput value={f.owner} onChange={set("owner")} placeholder="Responsible person" />
      </Field>
      <Field label="Site (optional)">
        <Select value={f.site || ""} onChange={set("site")}>
          <option value="">All sites</option>
          {(siteNames || []).map((s) => (
            <option key={s} value={s}>{s}</option>
          ))}
        </Select>
      </Field>
      <div className="grid grid-cols-2 gap-3.5">
        <Field label="Start">
          <TextInput type="date" value={f.start} onChange={set("start")} />
        </Field>
        <Field label="Finish">
          <TextInput type="date" value={f.end} onChange={set("end")} />
        </Field>
      </div>
      {linkedOpenIssues.length > 0 && (
        <div
          className="flex flex-col gap-1 px-3 py-2.5 rounded-lg text-sm"
          style={{ background: T.redSoft, color: T.red }}
        >
          <span className="flex items-center gap-2 font-medium">
            <AlertTriangle size={14} /> Delayed by {linkedOpenIssues.length > 1 ? "open issues" : "an open issue"}:
          </span>
          <ul className="list-disc pl-5">
            {linkedOpenIssues.map((i) => (
              <li key={i.id}>{i.description}</li>
            ))}
          </ul>
        </div>
      )}
      {isOverdueUnflagged && (
        <div
          className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-lg text-sm"
          style={{ background: T.amberSoft, color: T.amber }}
        >
          <span className="flex items-center gap-2">
            <Clock size={14} /> This task passed its finish date on {fmtDate(f.end)}.
          </span>
          <button
            type="button"
            onClick={() => setStatus({ target: { value: "Delayed" } })}
            className="shrink-0 font-medium underline"
          >
            Mark as delayed
          </button>
        </div>
      )}
      {f.status === "Delayed" && f.plannedEnd && (
        <p className="text-xs leading-relaxed" style={{ color: T.textFaint }}>
          Originally due {fmtDate(f.plannedEnd)}. The Gantt bar will only turn red from that
          date to the new Finish date above — set Finish to the revised date.
        </p>
      )}
      {showProgress ? (
        <div className="grid grid-cols-2 gap-3.5">
          <Field label="Status">
            <Select value={f.status} onChange={setStatus}>
              {TASK_STATUSES.map((s) => (
                <option key={s}>{s}</option>
              ))}
            </Select>
          </Field>
          <Field label="Progress (%)">
            <TextInput type="number" min="0" max="100" value={f.progress} onChange={set("progress")} />
          </Field>
        </div>
      ) : (
        <Field label="Status">
          <Select value={f.status} onChange={setStatus}>
            {TASK_STATUSES.map((s) => (
              <option key={s}>{s}</option>
            ))}
          </Select>
        </Field>
      )}
    </Modal>
  );
}

function TaskTemplatesModal({ department, data, onClose, onSave }) {
  const [groups, setGroups] = useState(
    data && data.length
      ? data.map((g) => ({ ...g, templates: (g.templates || []).map((t) => ({ ...t })) }))
      : [{ id: uid(), name: "", templates: [{ id: uid(), name: "", durationDays: 1, owner: "" }] }]
  );

  const updateGroupName = (gid, name) =>
    setGroups((prev) => prev.map((g) => (g.id === gid ? { ...g, name } : g)));
  const addGroup = () =>
    setGroups((prev) => [...prev, { id: uid(), name: "", templates: [{ id: uid(), name: "", durationDays: 1, owner: "" }] }]);
  const removeGroup = (gid) => setGroups((prev) => prev.filter((g) => g.id !== gid));

  const updateTemplate = (gid, tid, key, value) =>
    setGroups((prev) =>
      prev.map((g) =>
        g.id !== gid ? g : { ...g, templates: g.templates.map((t) => (t.id === tid ? { ...t, [key]: value } : t)) }
      )
    );
  const addTemplate = (gid) =>
    setGroups((prev) =>
      prev.map((g) =>
        g.id !== gid ? g : { ...g, templates: [...g.templates, { id: uid(), name: "", durationDays: 1, owner: "" }] }
      )
    );
  const removeTemplate = (gid, tid) =>
    setGroups((prev) =>
      prev.map((g) => (g.id !== gid ? g : { ...g, templates: g.templates.filter((t) => t.id !== tid) }))
    );

  const starter = DEFAULT_DEPT_TEMPLATES[department];
  const hasContent = groups.some((g) => g.name || g.templates.some((t) => t.name));
  const loadStarter = () => {
    if (hasContent && !confirm("This replaces everything currently in this form. Continue?")) return;
    setGroups(starter.map((g) => ({ ...g, id: uid(), templates: g.templates.map((t) => ({ ...t, id: uid() })) })));
  };

  const handleSubmit = () => {
    const cleaned = groups
      .map((g) => ({
        ...g,
        name: (g.name || "").trim(),
        templates: g.templates
          .map((t) => ({ ...t, name: (t.name || "").trim(), durationDays: Math.max(1, Number(t.durationDays) || 1) }))
          .filter((t) => t.name),
      }))
      .filter((g) => g.name && g.templates.length > 0);
    onSave(cleaned);
  };

  return (
    <Modal
      title={`Task templates${department ? ` — ${department}` : ""}`}
      onClose={onClose}
      onSubmit={handleSubmit}
      submitLabel="Save templates"
      wide
    >
      <p className="text-xs leading-relaxed" style={{ color: T.textFaint }}>
        Shared across every {department || ""} project — organize into categories the way your
        scope of works actually reads (e.g. "Painting - Surface Preparation" as one group of
        tasks). "Generate for sites" creates every task in every category, per site, back-to-back.
      </p>
      {starter && (
        <div
          className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-lg text-sm"
          style={{ background: T.accentSoft, color: T.accentText }}
        >
          <span>
            Load the {department} scope-of-works structure — task names and categories only.
            Durations default to 1 day; none were visible in the source, so review every one.
          </span>
          <Button type="button" variant="ghost" onClick={loadStarter}>Load starter list</Button>
        </div>
      )}
      <div className="flex flex-col gap-4">
        {groups.map((g) => (
          <div key={g.id} className="rounded-lg p-3 flex flex-col gap-2.5" style={{ border: `1px solid ${T.border}`, background: T.bgElevated }}>
            <div className="flex items-center gap-2">
              <TextInput
                value={g.name}
                onChange={(e) => updateGroupName(g.id, e.target.value)}
                placeholder="Category name, e.g. Painting - Surface Preparation"
                style={{ fontWeight: 600 }}
              />
              <IconBtn title="Remove category" danger onClick={() => removeGroup(g.id)}>
                <Trash2 size={16} />
              </IconBtn>
            </div>
            <div className="flex flex-col gap-2 pl-2">
              {g.templates.map((t, idx) => (
                <div key={t.id} className="flex flex-wrap items-end gap-2">
                  <div className="flex-1">
                    <Field label={idx === 0 ? "Task name" : undefined}>
                      <TextInput
                        value={t.name}
                        onChange={(e) => updateTemplate(g.id, t.id, "name", e.target.value)}
                        placeholder="e.g. Site Assessment"
                      />
                    </Field>
                  </div>
                  <div className="w-20 sm:w-24 shrink-0">
                    <Field label={idx === 0 ? "Days" : undefined}>
                      <TextInput
                        type="number"
                        min="1"
                        value={t.durationDays}
                        onChange={(e) => updateTemplate(g.id, t.id, "durationDays", e.target.value)}
                      />
                    </Field>
                  </div>
                  <div className="w-32 sm:w-40 shrink-0">
                    <Field label={idx === 0 ? "Default owner" : undefined}>
                      <TextInput
                        value={t.owner}
                        onChange={(e) => updateTemplate(g.id, t.id, "owner", e.target.value)}
                        placeholder="Optional"
                      />
                    </Field>
                  </div>
                  <IconBtn title="Remove task" danger onClick={() => removeTemplate(g.id, t.id)}>
                    <Trash2 size={16} />
                  </IconBtn>
                </div>
              ))}
              <Button variant="ghost" onClick={() => addTemplate(g.id)}>
                <Plus size={14} /> Add task
              </Button>
            </div>
          </div>
        ))}
      </div>
      <Button variant="ghost" onClick={addGroup}>
        <Plus size={15} /> Add category
      </Button>
    </Modal>
  );
}

function computeStaggeredDates(sites, firstStart, staggerDays, worksWeekends) {
  const map = {};
  sites.forEach((s, idx) => {
    map[s] = rollToWorkingDay(addDaysStr(firstStart, idx * (Number(staggerDays) || 0)), worksWeekends);
  });
  return map;
}

function BulkGenerateModal({ department, siteNames, groups, worksWeekends, onClose, onGenerate }) {
  const allTemplates = useMemo(() => (groups || []).flatMap((g) => g.templates || []), [groups]);

  const [selectedSites, setSelectedSites] = useState(() => new Set(siteNames));
  const [selectedTemplateIds, setSelectedTemplateIds] = useState(() => new Set(allTemplates.map((t) => t.id)));
  const [firstStart, setFirstStart] = useState(todayStr());
  const [staggerDays, setStaggerDays] = useState(7);
  const [siteDates, setSiteDates] = useState(() => computeStaggeredDates(siteNames, todayStr(), 7, worksWeekends));

  const toggleSite = (s) =>
    setSelectedSites((prev) => {
      const next = new Set(prev);
      if (next.has(s)) next.delete(s);
      else next.add(s);
      return next;
    });
  const toggleTemplate = (id) =>
    setSelectedTemplateIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  const toggleGroup = (g) =>
    setSelectedTemplateIds((prev) => {
      const ids = g.templates.map((t) => t.id);
      const allSelected = ids.length > 0 && ids.every((id) => prev.has(id));
      const next = new Set(prev);
      ids.forEach((id) => (allSelected ? next.delete(id) : next.add(id)));
      return next;
    });

  const recalculate = () => setSiteDates(computeStaggeredDates(siteNames, firstStart, staggerDays, worksWeekends));

  const noSites = siteNames.length === 0;
  const noTemplates = allTemplates.length === 0;
  const taskCount = selectedSites.size * selectedTemplateIds.size;

  const handleSubmit = () => {
    if (noSites || noTemplates || taskCount === 0) return;
    // Keep display order (category by category) so the sequential chain matches
    // how the scope of works actually reads top to bottom.
    const chosenTemplates = allTemplates.filter((t) => selectedTemplateIds.has(t.id));
    const newTasks = [];
    siteNames.forEach((site) => {
      if (!selectedSites.has(site)) return;
      let cursor = rollToWorkingDay(siteDates[site] || firstStart, worksWeekends);
      chosenTemplates.forEach((tpl) => {
        const dur = Math.max(1, Number(tpl.durationDays) || 1);
        const start = cursor;
        const end = addWorkingDaysStr(start, dur - 1, worksWeekends);
        newTasks.push({
          id: uid(),
          name: tpl.name,
          site,
          owner: tpl.owner || "",
          start,
          end,
          status: "Not Started",
          progress: 0,
          plannedEnd: "",
        });
        cursor = rollToWorkingDay(addDaysStr(end, 1), worksWeekends);
      });
    });
    onGenerate(newTasks);
  };

  if (noSites || noTemplates) {
    return (
      <Modal title="Generate tasks for sites" onClose={onClose} onSubmit={onClose} submitLabel="Close">
        <p className="text-sm leading-relaxed" style={{ color: T.textDim }}>
          {noSites
            ? "This project has no sites defined yet. Edit the project and add sites first."
            : `No ${department || ""} task templates defined yet. Use "Task templates" to build that department's library first.`}
        </p>
      </Modal>
    );
  }

  return (
    <Modal title={`Generate tasks for sites${department ? ` — ${department}` : ""}`} onClose={onClose} onSubmit={handleSubmit} submitLabel={`Generate ${taskCount} task${taskCount === 1 ? "" : "s"}`} wide>
      <p className="text-xs" style={{ color: T.textFaint }}>
        {worksWeekends
          ? "This project works weekends — durations count every day."
          : "This project is weekdays-only — durations skip Saturday and Sunday automatically."}
      </p>
      <div className="grid grid-cols-2 gap-3.5">
        <Field label="First site starts">
          <TextInput type="date" value={firstStart} onChange={(e) => setFirstStart(e.target.value)} />
        </Field>
        <Field label="Days between sites">
          <div className="flex gap-2">
            <TextInput type="number" min="0" value={staggerDays} onChange={(e) => setStaggerDays(e.target.value)} />
            <Button type="button" variant="ghost" onClick={recalculate}>Recalculate</Button>
          </div>
        </Field>
      </div>

      <div>
        <span className="block text-xs font-medium mb-1.5" style={{ color: T.textDim }}>
          Sites ({selectedSites.size} of {siteNames.length} selected)
        </span>
        <div className="flex flex-col gap-1.5 max-h-40 overflow-y-auto pr-1">
          {siteNames.map((s) => (
            <div key={s} className="flex items-center gap-2">
              <input type="checkbox" checked={selectedSites.has(s)} onChange={() => toggleSite(s)} />
              <span className="flex-1 text-sm truncate" style={{ color: T.text }}>{s}</span>
              <TextInput
                type="date"
                value={siteDates[s] || ""}
                onChange={(e) => setSiteDates((prev) => ({ ...prev, [s]: e.target.value }))}
                style={{ width: 150 }}
              />
            </div>
          ))}
        </div>
      </div>

      <div>
        <span className="block text-xs font-medium mb-1.5" style={{ color: T.textDim }}>
          Templates ({selectedTemplateIds.size} of {allTemplates.length} selected)
        </span>
        <div className="flex flex-col gap-3 max-h-64 overflow-y-auto pr-1">
          {(groups || []).map((g) => {
            const ids = g.templates.map((t) => t.id);
            const allSelected = ids.length > 0 && ids.every((id) => selectedTemplateIds.has(id));
            return (
              <div key={g.id} className="flex flex-col gap-1">
                <label className="flex items-center gap-2 text-sm font-medium" style={{ color: T.text, fontFamily: "'Space Grotesk', sans-serif" }}>
                  <input type="checkbox" checked={allSelected} onChange={() => toggleGroup(g)} />
                  {g.name}
                </label>
                <div className="pl-6 flex flex-col gap-1">
                  {g.templates.map((t) => (
                    <label key={t.id} className="flex items-center gap-2 text-sm" style={{ color: T.textDim }}>
                      <input type="checkbox" checked={selectedTemplateIds.has(t.id)} onChange={() => toggleTemplate(t.id)} />
                      {t.name} <span style={{ color: T.textFaint }}>({t.durationDays}d)</span>
                    </label>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <p className="text-xs leading-relaxed" style={{ color: T.textFaint }}>
        Each site's templates are scheduled back-to-back starting from that site's date above,
        category by category — the next task starts the day after the previous one ends. This
        will create {taskCount} task{taskCount === 1 ? "" : "s"}.
      </p>
    </Modal>
  );
}

